// LOCAL AUTH INTEGRATION (not a mock): uses an ephemeral Supabase CLI stack
// and Mailpit. Run ONLY with localhost keys generated by Supabase CLI.
// Does not contact hosted Supabase, a real mailbox, or Stripe.
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { runInNewContext } from "node:vm";
import { setTimeout as sleep } from "node:timers/promises";
import { createClient } from "@supabase/supabase-js";
import { verifyGuestWelcomeIdentity } from "../../supabase/functions/checkout/welcome-guest-verification.mjs";

const api = String(process.env.LOCAL_SUPABASE_URL || "");
const key = String(process.env.LOCAL_SUPABASE_ANON_KEY || "");
const mail = String(process.env.LOCAL_MAILPIT_URL || "http://127.0.0.1:54324");
function requireLoopback(value) {
  const u = new URL(value);
  assert.equal(u.protocol, "http:", "No remote or TLS-hosted test environments");
  assert.ok(["localhost", "127.0.0.1", "[::1]"].includes(u.hostname), "LOCAL ONLY: " + u.hostname);
}
requireLoopback(api);
requireLoopback(mail);
assert.ok(key.length >= 20, "Missing disposable local Auth publishable/anon key");
assert.equal(process.env.SUPABASE_ACCESS_TOKEN, undefined, "Do not link a hosted Supabase account");

const source = readFileSync(new URL("../../src/lib/welcomeGuestEmail.js", import.meta.url), "utf8");
assert.equal((source.match(/^import /gm) || []).length, 2, "App Auth module imports changed");
const script = source.replace(/^import .*\r?\n/gm, "").replace(/^export /gm, "");
function appGuestModule() {
  const context = { createClient, supabaseUrl: api, supabasePublishableKey: key, Date };
  runInNewContext(script + "\nglobalThis.testApi = { sendWelcomeGuestOtp, verifyWelcomeGuestOtp, welcomeGuestTokenFor, clearWelcomeGuestProof };", context);
  return context.testApi;
}
const guest = appGuestModule();
const serverAuth = createClient(api, key, {
  auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
});
function assertEmailIsLocal(value) {
  assert.match(value, /^welcome10-[a-z0-9-]+@example\.test$/);
}
async function waitForMail(email, ignoreIds = new Set()) {
  assertEmailIsLocal(email);
  for (let i = 0; i < 60; i++) {
    const response = await fetch(mail + "/api/v1/search?query=" + encodeURIComponent("to:" + email));
    if (response.ok) {
      const data = await response.json();
      for (const msg of data.messages || []) {
        if (ignoreIds.has(msg.ID)) continue;
        if (!(msg.To || []).some(to => String(to.Address || "").toLowerCase() === email)) continue;
        const bodyResponse = await fetch(mail + "/api/v1/message/" + encodeURIComponent(msg.ID));
        if (!bodyResponse.ok) continue;
        const body = await bodyResponse.json();
        const rendered = String(body.HTML || "") + "\n" + String(body.Text || "");
        const match = rendered.match(/WELCOME10-QA-CODE:\s*(\d{6})(?!\d)/);
        if (!match) continue;
        assert.doesNotMatch(rendered, /\{\{\s*\.Token\s*\}\}/, "Unrendered template would be invalid");
        return { id: msg.ID, token: match[1] };
      }
    }
    await sleep(1000);
  }
  throw Error("Mailpit did not receive the required numeric local OTP for " + email);
}
function wrongCode(code) {
  return String((Number(code) + 1) % 1_000_000).padStart(6, "0");
}
async function verifyIdentity(token, email) {
  return verifyGuestWelcomeIdentity(token, email, (jwt) => serverAuth.auth.getUser(jwt));
}
const newEmail = "welcome10-new-guest@example.test";
const expEmail = "welcome10-expiring-guest@example.test";
const wrongEmail = "welcome10-wrong-guest@example.test";

// New passwordless address must receive actual rendered email in local Mailpit.
await guest.sendWelcomeGuestOtp(newEmail);
const first = await waitForMail(newEmail);
assert.match(first.token, /^\d{6}$/);
await assert.rejects(() => guest.verifyWelcomeGuestOtp(newEmail, wrongCode(first.token)));
assert.equal(guest.welcomeGuestTokenFor(newEmail), null);
await guest.verifyWelcomeGuestOtp(newEmail, first.token);
const firstJwt = guest.welcomeGuestTokenFor(newEmail);
assert.ok(firstJwt && firstJwt.length >= 64);
const firstIdentity = await verifyIdentity(firstJwt, newEmail);
assert.ok(firstIdentity?.userId);
assert.equal(firstIdentity?.email, newEmail);
assert.equal(await verifyIdentity(firstJwt, wrongEmail), null);
assert.equal(await verifyIdentity("not-a-valid-session", newEmail), null);
assert.equal(appGuestModule().welcomeGuestTokenFor(newEmail), null, "New tab/refresh cannot inherit proof");
console.log("PASS local Auth new address, rendered Mailpit code, wrong code and exact-email JWT verification");

// Reusing a consumed OTP must be denied; returning guest must retain Auth ID.
await assert.rejects(() => guest.verifyWelcomeGuestOtp(newEmail, first.token));
await sleep(1300); // local Auth resend frequency
await guest.sendWelcomeGuestOtp(newEmail);
const returning = await waitForMail(newEmail, new Set([first.id]));
await guest.verifyWelcomeGuestOtp(newEmail, returning.token);
const secondJwt = guest.welcomeGuestTokenFor(newEmail);
const secondIdentity = await verifyIdentity(secondJwt, newEmail);
assert.equal(secondIdentity?.userId, firstIdentity.userId, "Returning guest must reuse the same Auth identity");
assert.equal(guest.welcomeGuestTokenFor(wrongEmail), null);
guest.clearWelcomeGuestProof();
assert.equal(guest.welcomeGuestTokenFor(newEmail), null);
console.log("PASS local Auth returning address, consumed code rejection and memory-only guest proof");

// Actual local GoTrue OTP expiry: local config sets otp_expiry = 60 seconds.
await guest.sendWelcomeGuestOtp(expEmail);
const expiring = await waitForMail(expEmail);
await sleep(65000);
await assert.rejects(() => guest.verifyWelcomeGuestOtp(expEmail, expiring.token),
  "Expired local Auth numeric code must fail");
assert.equal(guest.welcomeGuestTokenFor(expEmail), null);
console.log("PASS real 60-second local Auth OTP expiry (Mailpit only)");
console.log("PASS LOCAL AUTH + MAILPIT INTEGRATION: all scenarios; no hosted APIs, no production mutation");
